"""Create a self-contained interactive browser preview (no Streamlit/server needed)."""
from pathlib import Path
import json
import pandas as pd
from plotly.offline import get_plotlyjs
ROOT=Path(__file__).resolve().parent
P=ROOT/'data'/'house_prices.csv';R=ROOT/'data'/'private_rents.csv'
stock=pd.read_csv(ROOT/'data'/'london_dwelling_stock_2012_2025.csv',dtype={'code':str},usecols=['borough','code']).drop_duplicates()
cn=stock.set_index('code').borough.to_dict()
data={}
for mode,file,col in [('buy',P,'average_price_gbp'),('rent',R,'rent_gbp')]:
 df=pd.read_csv(file,dtype={'code':str},keep_default_na=True)
 grouped={}
 for code,g in df.groupby('code'):
  g=g.sort_values('date')
  rows=[]
  for x in g.itertuples(index=False):
   d={'date':x.date,'value':round(float(getattr(x,col)),1)}
   if mode=='rent':
    d['growth']=round(float(x.rent_annual_change_pct),2) if pd.notna(x.rent_annual_change_pct) else None
    d['bedrooms']=[round(float(getattr(x,f'rent_{n}_gbp')),1) if pd.notna(getattr(x,f'rent_{n}_gbp')) else None for n in ['1bed','2bed','3bed','4plus']]
   rows.append(d)
  grouped[code]={'name':'London' if code=='E12000007' else cn.get(code,g.borough.iloc[0]),'points':rows}
 data[mode]={'latest':df.date.max(),'series':grouped}
json_data=json.dumps(data,separators=(',',':')).replace('</','<\\/')
plotly_js=get_plotlyjs()
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>London Housing Costs | Objective 2 Preview</title><style>
:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:#17294a;background:#f5f8fc}*{box-sizing:border-box}body{margin:0}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:100vh}.side{background:#edf2f9;border-right:1px solid #dfe6f1;padding:34px 22px;position:sticky;top:0;height:100vh}.side h2{font-size:18px;margin-top:8px}.label{font-size:11px;letter-spacing:.14em;color:#6380a1;font-weight:800}.side select{width:100%;border:1px solid #d7e0eb;border-radius:10px;padding:13px 10px;background:#fff;color:#17294a;font-size:14px;margin-top:9px}.field{margin-top:27px}.hint{font-size:12px;color:#6c7c92;line-height:1.55}.main{max-width:1330px;width:100%;padding:38px 45px 60px;margin:auto}.main h1{font-size:36px;letter-spacing:-.035em;margin:5px 0 10px}.lede{color:#5d6e83;max-width:870px;line-height:1.6}.tabs{display:flex;gap:10px;margin:25px 0 18px}.tab{border:1px solid #cbd9e9;background:white;color:#234765;border-radius:10px;padding:11px 24px;cursor:pointer;font-weight:700}.tab.active{background:#234d87;color:white;border-color:#234d87}.meta{color:#64748b;font-size:13px;margin-bottom:20px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.card{min-height:110px;background:#fff;border:1px solid #e0e7f0;border-radius:14px;padding:19px}.card-label{color:#62778e;font-size:12px;margin-bottom:12px}.card-val{font-size:26px;font-weight:780;letter-spacing:-.04em}.card-note{font-size:12px;color:#75869b;margin-top:8px}.section{margin-top:28px;padding:25px 25px 10px;background:#fff;border:1px solid #e0e7f0;border-radius:17px}.section h2{font-size:20px;margin:8px 0}.section p{color:#697e94;font-size:13px}.chart{width:100%}.foot{color:#697e94;font-size:12px;line-height:1.65;margin-top:20px}.map-empty{border:1px dashed #bdcddd;border-radius:10px;min-height:100px;background:#f8fafc;color:#65788f;display:flex;align-items:center;justify-content:center;text-align:center;padding:20px}.flag{background:#e8f0fb;color:#315b93;padding:6px 10px;border-radius:100px;font-size:11px;font-weight:700}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}#rentOnly{display:none}@media(max-width:930px){.layout{grid-template-columns:1fr}.side{position:static;height:auto;display:flex;align-items:center;gap:18px;flex-wrap:wrap}.side .field{margin:0}.main{padding:26px 15px}.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.cards{grid-template-columns:1fr}.card{min-height:90px}.section{padding:15px 5px}.main h1{font-size:28px}}
</style><script>''' + plotly_js + '''</script></head><body><div class="layout"><aside class="side"><div><div class="label">HOUSING CAPACITY TOOL</div><h2>Explore housing costs</h2></div><div class="field"><label class="label" for="borough">GEOGRAPHY</label><select id="borough"></select></div><div class="field"><label class="label" for="period">TREND PERIOD</label><select id="period"><option value="5">Last 5 years</option><option value="3">Last 3 years</option><option value="10">Last 10 years</option><option value="0">All available</option></select></div><p class="hint">This browser preview uses your actual uploaded house-price and rental-cost data. Switch between buying and renting, then select a borough.</p></aside><main class="main"><div class="row"><div class="label">OBJECTIVE 02 · HOUSING COSTS</div><span class="flag">Offline interactive preview</span></div><h1>The cost of housing in London</h1><p class="lede">How much does housing cost, which boroughs are more expensive, and how have buying prices and private rents changed over time?</p><div class="tabs"><button class="tab active" id="tabRent">🏠 &nbsp;Renting</button><button class="tab" id="tabBuy">🔑 &nbsp;Buying</button></div><div class="meta" id="meta"></div><div class="cards" id="cards"></div><section class="section"><div class="label">VIEW 01 · BOROUGH RANKING</div><h2>Where is housing most expensive?</h2><p>The dotted line is the published London regional estimate, not the average of borough figures.</p><div id="ranking" class="chart" style="height:800px"></div></section><section class="section"><div class="label">VIEW 02 · HISTORICAL TRENDS</div><h2>How have housing costs changed over time?</h2><p>Compare a selected borough with the London benchmark.</p><div id="trend" class="chart" style="height:385px"></div></section><section class="section" id="rentSection"><div class="label">VIEW 03 · PROPERTY SIZE</div><h2>Monthly private rent by bedroom count</h2><p id="bedroomLabel"></p><div id="bedrooms" class="chart" style="height:330px"></div></section><section class="section"><div class="label" id="mapLabel">VIEW 04 · LONDON MAP</div><h2>Geographical pattern of housing costs</h2><div class="map-empty">The interactive choropleth map is implemented in the Streamlit project. This self-contained preview does not bundle geographical polygons; the app retrieves or accepts the official GLA GeoJSON.</div></section><p class="foot">Sources: UK House Price Index (Land Registry / ONS) and ONS Price Index of Private Rents. HPI estimates through July 2026; rental estimates through August 2026. Annual movements and values are estimates, subject to source methodologies and revisions. Rental data are not published separately for the City of London. Cost is not the same as affordability.</p></main></div><script>
const DATA=''' +json_data+ ''';
let mode='rent';const borough=document.getElementById('borough'),period=document.getElementById('period');
function pound(n){return '£'+Math.round(n).toLocaleString('en-GB')};function month(d){return new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric'})};
const city='E09000001', london='E12000007';
function setTab(which){mode=which;document.getElementById('tabRent').classList.toggle('active',mode==='rent');document.getElementById('tabBuy').classList.toggle('active',mode==='buy');document.getElementById('rentSection').style.display=mode==='rent'?'block':'none';document.getElementById('mapLabel').textContent=mode==='rent'?'VIEW 04 · LONDON MAP':'VIEW 03 · LONDON MAP';render()}
function render(){const m=DATA[mode],s=m.series;let code=borough.value;if(mode==='rent'&&code===city){document.getElementById('meta').textContent='City of London rents unavailable · Showing London regional benchmark instead';code=london}else{document.getElementById('meta').textContent=month(m.latest)+' · '+(mode==='rent'?'Estimated monthly private rents · 32 London boroughs':'Estimated purchase prices · 33 London local authority areas')};
const focus=s[code].points,lp=s[london].points,latest=focus[focus.length-1],lastLondon=lp[lp.length-1],priceLabel=mode==='rent'?'Average monthly rent':'Average property price';
let annual=latest.growth;if(mode==='buy'){const prior=focus.find(p=>p.date.slice(0,4)===String(parseInt(m.latest.slice(0,4))-1)&&p.date.slice(5)===m.latest.slice(5));annual=prior?100*(latest.value/prior.value-1):null}
const all=Object.entries(s).filter(([k,v])=>k.startsWith('E09')).map(([k,v])=>({code:k,name:v.name,value:v.points[v.points.length-1].value})).sort((a,b)=>b.value-a.value);
const selectedName=code===london?'London':s[code].name;const rank=all.findIndex(b=>b.code===code)+1;let cards=[{label:priceLabel,val:pound(latest.value),note:selectedName},{label:'Annual change',val:annual==null?'N/A':(annual>0?'+':'')+annual.toFixed(1)+'%',note:'Compared with 12 months earlier'}];if(code===london){cards.push({label:'Highest-cost borough',val:all[0].name,note:pound(all[0].value)},{label:'Lowest-cost borough',val:all[all.length-1].name,note:pound(all[all.length-1].value)})}else{const diff=100*(latest.value/lastLondon.value-1);cards.push({label:'Vs London benchmark',val:(diff>0?'+':'')+diff.toFixed(1)+'%',note:pound(lastLondon.value)+' London estimate'},{label:'Cost ranking',val:rank+' of '+all.length,note:'Rank 1 = highest cost'})}document.getElementById('cards').innerHTML=cards.map(c=>`<div class="card"><div class="card-label">${c.label}</div><div class="card-val">${c.val}</div><div class="card-note">${c.note}</div></div>`).join('');
const asc=all.slice().reverse(),cols=asc.map(x=>x.code===code&&code!==london?'#2563eb':'#a7c4df');Plotly.react('ranking',[{type:'bar',orientation:'h',x:asc.map(x=>x.value),y:asc.map(x=>x.name),marker:{color:cols},hovertemplate:'%{y}<br>£%{x:,.0f}<extra></extra>'}],{margin:{l:165,r:22,t:25,b:50},paper_bgcolor:'#fff',plot_bgcolor:'#fff',font:{color:'#17294a',size:11},showlegend:false,shapes:[{type:'line',x0:lastLondon.value,x1:lastLondon.value,yref:'paper',y0:0,y1:1,line:{color:'#d98136',dash:'dash',width:2}}],xaxis:{tickprefix:'£',tickformat:',',gridcolor:'#edf2f8',title:mode==='rent'?'Monthly rent (£)':'Property price (£)'},yaxis:{automargin:false}},{responsive:true,displayModeBar:false});
let allowed=m.series[code].points;const yr=parseInt(period.value);if(yr){const lim=new Date(m.latest+'T12:00:00Z');lim.setFullYear(lim.getFullYear()-yr);allowed=allowed.filter(p=>new Date(p.date+'T12:00:00Z')>=lim)};let benchmark=m.series[london].points.filter(p=>allowed.length&&p.date>=allowed[0].date);let traces=[{type:'scatter',mode:'lines',name:'London benchmark',x:benchmark.map(p=>p.date),y:benchmark.map(p=>p.value),line:{color:'#d98136',width:3} }];if(code!==london)traces.push({type:'scatter',mode:'lines',name:s[code].name,x:allowed.map(p=>p.date),y:allowed.map(p=>p.value),line:{color:'#2563eb',width:3}});Plotly.react('trend',traces,{margin:{l:75,r:20,t:12,b:45},paper_bgcolor:'#fff',plot_bgcolor:'#fff',font:{color:'#17294a',size:12},legend:{orientation:'h',y:-.25},xaxis:{gridcolor:'#edf2f8'},yaxis:{tickprefix:'£',tickformat:',',gridcolor:'#edf2f8'}},{responsive:true,displayModeBar:false});
if(mode==='rent'){document.getElementById('bedroomLabel').textContent=selectedName+' · '+month(m.latest);const vals=latest.bedrooms;Plotly.react('bedrooms',[{type:'bar',x:['1 bedroom','2 bedrooms','3 bedrooms','4+ bedrooms'],y:vals,marker:{color:['#9fbedc','#639fcd','#2563eb','#17294a']},text:vals.map(pound),textposition:'outside',hovertemplate:'%{x}<br>£%{y:,.0f}/month<extra></extra>'}],{margin:{l:80,r:20,t:25,b:45},paper_bgcolor:'#fff',plot_bgcolor:'#fff',font:{color:'#17294a',size:12},yaxis:{tickprefix:'£',tickformat:',',gridcolor:'#edf2f8',range:[0,Math.max(...vals)*1.18]}},{responsive:true,displayModeBar:false})}
}
Object.entries(DATA.buy.series).filter(([c])=>c.startsWith('E09')).sort((a,b)=>a[1].name.localeCompare(b[1].name)).forEach(([code,val])=>{const option=document.createElement('option');option.value=code;option.textContent=val.name;borough.appendChild(option)});const londonOpt=document.createElement('option');londonOpt.value=london;londonOpt.textContent='All London';borough.insertBefore(londonOpt,borough.firstChild);borough.value=london;borough.addEventListener('change',render);period.addEventListener('change',render);document.getElementById('tabRent').addEventListener('click',()=>setTab('rent'));document.getElementById('tabBuy').addEventListener('click',()=>setTab('buy'));render();
</script></body></html>'''
(ROOT/'cost_dashboard_preview.html').write_text(html,encoding='utf-8')
print('Preview created',ROOT/'cost_dashboard_preview.html',round((ROOT/'cost_dashboard_preview.html').stat().st_size/1e6,2),'MB')
